<?php use FilamentManager\Core\View; ?>
<h1><?= View::t('settings') ?></h1><div class="cards">
<section class="card"><h2><?= View::t('version') ?></h2><p><strong><?= View::e($currentVersion) ?></strong></p><form method="post" action="<?= View::e($basePath) ?>/admin/settings/update/check"><?= View::csrf() ?><button><?= View::t('check_updates') ?></button></form>
<?php if(is_array($update)): ?><p><?= $update['available'] ? View::e(View::t('new_version_available',['version'=>$update['latest']])) : View::t('up_to_date') ?></p><?php if($update['available']): ?><details><summary><?= View::t('install_version',['version'=>$update['latest']]) ?></summary><p class="muted"><?= View::t('update_backup_note') ?></p><form method="post" action="<?= View::e($basePath) ?>/admin/settings/update/install"><?= View::csrf() ?><input type="hidden" name="version" value="<?= View::e($update['latest']) ?>"><label><?= View::t('password') ?><input name="password" type="password" required autocomplete="current-password"></label><button><?= View::t('update_server') ?></button></form></details><?php endif; ?><?php endif; ?></section>
<section class="card"><h2><?= View::t('backup_restore') ?></h2><form method="post" action="<?= View::e($basePath) ?>/admin/settings/backup"><?= View::csrf() ?><button><?= View::t('create_download_backup') ?></button></form><h3><?= View::t('stored_backups') ?></h3><ul><?php foreach(array_slice($backups,0,10) as $backup): ?><li><code><?= View::e($backup['name']) ?></code> · <?= View::e(number_format($backup['size']/1024,1,',',' ')) ?> KiB</li><?php endforeach; ?><?php if(!$backups): ?><li><?= View::t('none') ?></li><?php endif; ?></ul><hr>
<details><summary><?= View::t('restore_backup') ?></summary><p class="notice error"><?= View::t('restore_warning') ?></p><form method="post" enctype="multipart/form-data" action="<?= View::e($basePath) ?>/admin/settings/restore"><?= View::csrf() ?><label><?= View::t('backup_file') ?><input name="backup" type="file" accept=".zip,application/zip" required></label><label><?= View::t('password') ?><input name="password" type="password" required autocomplete="current-password"></label><button><?= View::t('restore_data') ?></button></form></details></section>
<section class="card"><h2><?= View::t('security') ?></h2><?php if(!$securityIssues): ?><p class="notice success"><?= View::t('security_ok') ?></p><?php else: ?><ul><?php foreach($securityIssues as $issue): ?><li><?= View::e($issue) ?></li><?php endforeach; ?></ul><?php endif; ?><p class="muted"><?= View::t('document_root_help') ?></p></section></div>
